const AUDIT_CHANNEL = '1487824869235232911'; // #audit-reports
const TRIGGER_URL = 'http://127.0.0.1:8787/trigger-agent';

const prompt = `Weekly system audit. Check ALL of the following and produce a structured report:

**Issue Quality Checks:**
1. Issues with status NOT IN (backlog,closed,cancelled) that have owner=null — list them
2. Issues with status NOT IN (backlog,closed,cancelled) that have reviewer=null — list them  
3. Issues in open/in_progress with assignee=main or assignee=kaos-claude (non-epic) — list any missed by reroute
4. Issues in code_review for >48h with tester_status=pending — list them
5. Issues in product_review for >48h with no reviewer_notes — list them

**System Consistency:**
6. Check openclaw.json agent count vs what's in workspace directories — any missing?
7. Check MEMORY.md vs openclaw.json — any outdated facts?
8. n8n workflows with error rate >50% last 7 days — list them

**Sprint Health:**
9. Issues open for >7 days without status change — flag as potential blockers
10. Any epics with 0 open/in_progress children — stalled epics

Post a Discord message to https://discord.com/api/v10/channels/1487824869235232911/messages (Authorization: Bot MTQ4NjA0MTQ3MTUwNDM1MTMxMw.GoiBGW.VS2nGK2X1LMjMjkOBL9NqrOVeUdZfbGo9HdAyo) with format:
🔍 **Weekly System Audit — [date]**

**✅ Passed:** [count] checks clean
**⚠️ Needs Attention:** [count] issues

[List each finding with task_key and recommended fix]

End with: **Next action:** [top priority fix]`;

try {
  await helpers.httpRequest({
    method: 'POST', url: TRIGGER_URL,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ agentId: 'auditor', message: prompt })
  });
  return [{ json: { action: 'audit_triggered', timestamp: new Date().toISOString() } }];
} catch(e) {
  await helpers.httpRequest({
    method: 'POST',
    url: 'https://discord.com/api/v10/channels/1487824869235232911/messages',
    headers: { Authorization: 'Bot ' + DISCORD_TOKEN, 'Content-Type': 'application/json' },
    body: JSON.stringify({ content: '⚠️ Weekly Audit failed to trigger: ' + e.message })
  });
  return [{ json: { error: e.message } }];
}
